import{z as m,x as p,o as t,c as d,q as n,j as l,D as s,d as r,s as o,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"不动点与 Knaster–Tarski","description":"","frontmatter":{"title":"不动点与 Knaster–Tarski","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knaster-tarski-fixpoint.md","filePath":"cs/knaster-tarski-fixpoint.md","lastUpdated":1791063341000}'),A={name:"cs/knaster-tarski-fixpoint.md"};function B(u,a,h,k,c,F){const i=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="不动点与-knaster–tarski" tabindex="-1">不动点与 Knaster–Tarski <a class="header-anchor" href="#不动点与-knaster–tarski" aria-label="Permalink to &quot;不动点与 Knaster–Tarski&quot;">​</a></h1><div class="epigraph"><p>完备格上单调函数必有最小、最大不动点，分别是从底迭代的并与从顶迭代的交。循环语义、类型、时序逻辑都用这一颗钉子。</p><footer>—— 据 Tarski, A Lattice-Theoretical Fixpoint Theorem, 1955；Winskel 整理</footer></div><p>上一课<a href="/cs/weakest-precondition">最弱前置</a> 把 while 写成方程 \\(I=\\Phi(I)\\)。<a href="/cs/combinators-fixed-point">λ 课的 \\(Y\\)</a> 是语法等式，不管最小。缺口是<strong>格上的定理</strong>：Knaster–Tarski。模型检验用 \\(\\mu,\\nu\\) 算可达与循环，本课先给数学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完备格：任意子集有上确界、下确界（幂集、断言蕴含的商）。\\(F\\) 单调：\\(x\\le y\\Rightarrow F(x)\\le F(y)\\)。则 \\(\\mu F=\\bigwedge\\{x\\mid F(x)\\le x\\}\\) 是最小不动点，\\(\\nu F=\\bigvee\\{x\\mid x\\le F(x)\\}\\) 最大。Kleene：若 \\(F\\) 连续，则 \\(\\mu F=\\bigvee_n F^n(\\bot)\\)。有限格上从 \\(\\bot\\) 迭代必停。</p><p>部分正确的循环不变量可看成某种前不动点；存活、无穷路径常用最大不动点。</p><p><span class="marginnote">术语翻译：完备格就是「任何一堆元素都找得到最小上界与最大下界」的偏序集。直觉例子：把 \\(\\{s_0,s_1,s_2\\}\\) 的全部 8 个子集按「包含关系」排起来，任意一族子集都能取并、取交，所以它必是完备格，Tarski 定理在这里直接可用。</span></p><h3 id="不是-banach-压缩" tabindex="-1">不是 Banach 压缩 <a class="header-anchor" href="#不是-banach-压缩" aria-label="Permalink to &quot;不是 Banach 压缩&quot;">​</a></h3><p>度量空间的压缩映像是另一定理，要距离。这里是序。不要把 \\(Y\\) 与 \\(\\mu\\) 写成同一个对象：无类型 \\(Y\\) 不保证最小。</p><p><span class="marginnote">Tarski 1955；Knaster 更早的集合论形式。Winskel、Clarke et al. 模型检验教材用 \\(\\mu\\)-演算。本课不写 \\(\\mu\\)-演算语法全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在有限幂集上取 \\(F(X)=\\{s_0\\}\\cup\\mathrm{Post}(X)\\)，最小不动点 = 可达。对偶 \\(\\nu\\) 给「总能回到」。指出：抽象解释把格换成抽象域，单调保证迭代有意义，精度另说。</p>',12)),(t(),l(E,null,{default:s(()=>[o(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22%E5%AE%8C%E5%A4%87%E6%A0%BC%22%5D%20--%3E%20MON%5B%22%E5%8D%95%E8%B0%83%20F%22%5D%0A%20%20MON%20--%3E%20MU%5B%22%CE%BCF%20%E6%9C%80%E5%B0%8F%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20MON%20--%3E%20NU%5B%22%CE%BDF%20%E6%9C%80%E5%A4%A7%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了 \\(\\mu/\\nu\\)，CTL 的 \\(\\mathrm{EF},\\mathrm{EG}\\) 可定义成不动点，下一课模型检验具体算。Hoare 不变式是人提供的前不动点上界；算法要从 \\(\\bot\\) 爬。有限状态保证停；无限状态要抽象或归纳。",-1)),a[5]||(a[5]=e("p",null,"与递归定理：那里保证 TM 编码不动点存在，不给最小语义。",-1)),a[6]||(a[6]=e("p",null,"Kleene 链：\\(\\bot\\le F(\\bot)\\le F^2(\\bot)\\le\\cdots\\)，连续时并就是 \\(\\mu F\\)。有限格上单调即连续。抽象解释：Galois 连接把具体 \\(\\mu\\) 换成抽象格上的过近似，可靠但不完备。类型推导、数据流分析（到达定义）都是同一迭代，主干编译课已见，此处给定理名。",-1)),(t(),l(E,null,{default:s(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E4%BB%8E%20%E2%8A%A5%20%3D%20%E7%A9%BA%E9%9B%86%E5%87%BA%E5%8F%91%22%5D%20--%3E%20S1%5B%22%E7%AC%AC%201%20%E8%BD%AE%3A%20%7Bs0%7D%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E7%AC%AC%202%20%E8%BD%AE%3A%20%7Bs0%2C%20s1%7D%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E7%AC%AC%203%20%E8%BD%AE%3A%20%7Bs0%2C%20s1%2C%20s2%7D%22%5D%0A%20%20S3%20--%3E%20EQ%7B%22%E8%BF%99%E4%B8%80%E8%BD%AE%E4%B8%8E%E4%B8%8A%E4%B8%80%E8%BD%AE%E7%9B%B8%E5%90%8C%3F%22%7D%0A%20%20EQ%20--%3E%7C%22%E5%90%A6%22%7C%20S1%0A%20%20EQ%20--%3E%7C%22%E6%98%AF%22%7C%20STOP%5B%22%E5%81%9C%3A%20%CE%BCF%20%3D%20%E5%8F%AF%E8%BE%BE%E9%9B%86%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：三状态系统取 \\(F(X)=\\{s_0\\}\\cup\\mathrm{Post}(X)\\)，从空集爬起依次得 \\(\\{s_0\\}\\)、\\(\\{s_0,s_1\\}\\)、\\(\\{s_0,s_1,s_2\\}\\)，第 4 轮不再变大即停。有限格最多迭代「状态数 + 1」轮，这就是「有限则可算」的具体含义。</span></p><p><span class="marginnote">常见误区：初学者容易把 \\(\\mu F\\) 与 λ 演算的 \\(Y\\) 组合子混为一谈。\\(Y\\) 只保证语法等式 \\(Yf=f(Yf)\\) 有解，不挑解的大小；\\(\\mu F\\) 特指按序最小的那个解。模型检验要的正是最小解，拿 \\(Y\\) 顶替会得到没有语义保证的对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Tarski 全文，不引入范畴论初始代数。不把微分方程当不动点课。后课默认：循环与时序性质 = 单调算子的 \\(\\mu/\\nu\\)。下一课模型检验直觉。</p><p>幂集上的后像、\\(\\mathrm{wp}\\) 的循环、CTL 的 \\(\\mathrm{EF}/\\mathrm{EG}\\) 都是单调 \\(F\\) 的 \\(\\mu/\\nu\\)。有限则迭代可算。无类型 \\(Y\\) 不保证最小，不要混用。模型检验下一课开始落地。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完备格 + 单调 \\(F\\) \\(\\Rightarrow\\) 最小/最大不动点。</li><li>有限时 Kleene 迭代可算；可达是典型 \\(\\mu\\)。</li><li>与无类型 \\(Y\\) 分工：语义最小 vs 语法等式。</li><li>出处：Tarski, 1955；Knaster；Winskel。</li></ul>',7))])}const C=m(A,[["render",B]]);export{_ as __pageData,C as default};
